(1, 'self-intro', 'lessonMeta', '{"id":"self-intro","title":{"en":"到达机场 / Arrival at the airport","fr":"到达机场 / Arrivée à l’aéroport"},"scenario":{"en":"Move through the first airport steps after landing in China: pass border control, find baggage claim, handle a missing bag, leave the terminal, and show an address to a driver.","fr":"Avancer dans les premières étapes à l’aéroport après l’arrivée en Chine : passer le contrôle aux frontières, trouver les bagages, signaler un bagage manquant, sortir du terminal et montrer une adresse au chauffeur."}}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(2, 'self-intro', 'lessonMeta', '{"id":"self-intro","title":{"en":"到达机场 / Arrival at the airport","fr":"到达机场 / Arrivée à l’aéroport"},"scenario":{"en":"Move through the first airport steps after landing in China: pass border control, find baggage claim, handle a missing bag, leave the terminal, and show an address to a driver.","fr":"Avancer dans les premières étapes à l’aéroport après l’arrivée en Chine : passer le contrôle aux frontières, trouver les bagages, signaler un bagage manquant, sortir du terminal et montrer une adresse au chauffeur."}}', 'draft', 1, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(3, 'self-intro', 'dialogue', '{"title":{"en":"From border control to the taxi pickup","fr":"Du contrôle aux frontières jusqu’au taxi"},"lines":[{"id":"self-intro-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"您好。请问，您能帮我一下吗？","pinyin":"Nín hǎo. Qǐngwèn, nín néng bāng wǒ yíxià ma?","translation":{"en":"Hello. Excuse me, could you help me?","fr":"Bonjour. Excusez-moi, pouvez-vous m’aider ?"},"explanation":{"en":"您好 is the safer polite opener when you need help from airport staff or a driver.","fr":"您好 est une formule plus polie et plus sûre pour demander de l’aide au personnel de l’aéroport ou à un chauffeur."},"audio":"/audio/self-intro/line-01.mp3"},{"id":"self-intro-line-02","speaker":{"en":"Officer","fr":"Agent"},"hanzi":"您好。请出示您的护照。","pinyin":"Nín hǎo. Qǐng chūshì nín de hùzhào.","translation":{"en":"Hello. Please show your passport.","fr":"Bonjour. Veuillez présenter votre passeport."},"explanation":{"en":"At border control, the officer will use 请出示 to ask for your documents.","fr":"Au contrôle aux frontières, l’agent utilise 请出示 pour demander vos documents."},"audio":"/audio/self-intro/line-02.mp3"},{"id":"self-intro-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"这是我的护照。","pinyin":"Zhè shì wǒ de hùzhào.","translation":{"en":"This is my passport.","fr":"Voici mon passeport."},"explanation":{"en":"Respond to the officer with 这是我的护照 while handing over your passport.","fr":"Réponds à l’agent avec 这是我的护照 en tendant ton passeport."},"audio":"/audio/self-intro/line-03.mp3"},{"id":"self-intro-line-04","speaker":{"en":"Officer","fr":"Agent"},"hanzi":"您来中国做什么？您打算停留多久？","pinyin":"Nín lái Zhōngguó zuò shénme? Nín dǎsuàn tíngliú duōjiǔ?","translation":{"en":"What are you coming to China for? How long do you plan to stay?","fr":"Que venez-vous faire en Chine ? Combien de temps comptez-vous rester ?"},"explanation":{"en":"These questions combine 来…做什么 (purpose of visit) and 停留多久 (length of stay).","fr":"Ces questions combinent 来…做什么 (motif du séjour) et 停留多久 (durée du séjour)."},"audio":"/audio/self-intro/line-04.mp3"},{"id":"self-intro-line-05","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"我是来旅游的，大概两个星期。","pinyin":"Wǒ shì lái lǚyóu de, dàgài liǎng gè xīngqī.","translation":{"en":"I am here for tourism, about two weeks.","fr":"Je viens pour le tourisme, environ deux semaines."},"explanation":{"en":"我是来…的 is the key pattern for stating your purpose. Choose a simple word like 旅游 and a round number.","fr":"我是来…的 est la structure clé pour indiquer le motif. Choisis un mot simple comme 旅游 et un nombre rond."},"audio":"/audio/self-intro/line-05.mp3"},{"id":"self-intro-line-06","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"请问行李提取处在哪里？","pinyin":"Qǐngwèn xíngli tíqǔchù zài nǎlǐ?","translation":{"en":"Excuse me, where is baggage claim?","fr":"Excusez-moi, où se trouve la zone de récupération des bagages ?"},"explanation":{"en":"请问…在哪里？ is the main airport navigation pattern in this lesson.","fr":"请问…在哪里？ est la structure principale pour s’orienter dans l’aéroport."},"audio":"/audio/self-intro/line-06.mp3"},{"id":"self-intro-line-07","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"我的行李还没到。请问问询台在哪里？","pinyin":"Wǒ de xíngli hái méi dào. Qǐngwèn wènxúntái zài nǎlǐ?","translation":{"en":"My luggage has not arrived yet. Where is the information desk?","fr":"Mon bagage n’est pas encore arrivé. Où se trouve le bureau d’information ?"},"explanation":{"en":"Use 还没到 for something expected but not here yet, then ask where to get help.","fr":"Utilise 还没到 pour quelque chose d’attendu mais pas encore arrivé, puis demande où obtenir de l’aide."},"audio":"/audio/self-intro/line-07.mp3"},{"id":"self-intro-line-08","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"请问出口在哪里？请问出租车在哪里？","pinyin":"Qǐngwèn chūkǒu zài nǎlǐ? Qǐngwèn chūzūchē zài nǎlǐ?","translation":{"en":"Excuse me, where is the exit? Where are the taxis?","fr":"Excusez-moi, où est la sortie ? Où sont les taxis ?"},"explanation":{"en":"After baggage, the next useful steps are finding the exit and the taxi area.","fr":"Après les bagages, les étapes utiles sont de trouver la sortie puis la zone des taxis."},"audio":"/audio/self-intro/line-08.mp3"},{"id":"self-intro-line-09","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"我想去这个地址。请到这里。","pinyin":"Wǒ xiǎng qù zhège dìzhǐ. Qǐng dào zhèlǐ.","translation":{"en":"I want to go to this address. Please go here.","fr":"Je voudrais aller à cette adresse. Allez ici, s’il vous plaît."},"explanation":{"en":"Point to a saved address and say this instead of explaining where you are staying.","fr":"Montre une adresse enregistrée et dis cela au lieu d’expliquer où tu loges."},"audio":"/audio/self-intro/line-09.mp3"},{"id":"self-intro-line-10","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"大概需要多久？大概多少钱？","pinyin":"Dàgài xūyào duōjiǔ? Dàgài duōshǎo qián?","translation":{"en":"About how long will it take? About how much will it cost?","fr":"Cela prend environ combien de temps ? Cela coûte environ combien ?"},"explanation":{"en":"大概 softens the question when you only need an estimate before the ride starts.","fr":"大概 adoucit la question quand tu veux seulement une estimation avant le trajet."},"audio":"/audio/self-intro/line-10.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(4, 'self-intro', 'dialogue', '{"title":{"en":"From border control to the taxi pickup","fr":"Du contrôle aux frontières jusqu’au taxi"},"lines":[{"id":"self-intro-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"您好。请问，您能帮我一下吗？","pinyin":"Nín hǎo. Qǐngwèn, nín néng bāng wǒ yíxià ma?","translation":{"en":"Hello. Excuse me, could you help me?","fr":"Bonjour. Excusez-moi, pouvez-vous m’aider ?"},"explanation":{"en":"您好 is the safer polite opener when you need help from airport staff or a driver.","fr":"您好 est une formule plus polie et plus sûre pour demander de l’aide au personnel de l’aéroport ou à un chauffeur."},"audio":"/audio/self-intro/line-01.mp3"},{"id":"self-intro-line-02","speaker":{"en":"Officer","fr":"Agent"},"hanzi":"您好。请出示您的护照。","pinyin":"Nín hǎo. Qǐng chūshì nín de hùzhào.","translation":{"en":"Hello. Please show your passport.","fr":"Bonjour. Veuillez présenter votre passeport."},"explanation":{"en":"At border control, the officer will use 请出示 to ask for your documents.","fr":"Au contrôle aux frontières, l’agent utilise 请出示 pour demander vos documents."},"audio":"/audio/self-intro/line-02.mp3"},{"id":"self-intro-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"这是我的护照。","pinyin":"Zhè shì wǒ de hùzhào.","translation":{"en":"This is my passport.","fr":"Voici mon passeport."},"explanation":{"en":"Respond to the officer with 这是我的护照 while handing over your passport.","fr":"Réponds à l’agent avec 这是我的护照 en tendant ton passeport."},"audio":"/audio/self-intro/line-03.mp3"},{"id":"self-intro-line-04","speaker":{"en":"Officer","fr":"Agent"},"hanzi":"您来中国做什么？您打算停留多久？","pinyin":"Nín lái Zhōngguó zuò shénme? Nín dǎsuàn tíngliú duōjiǔ?","translation":{"en":"What are you coming to China for? How long do you plan to stay?","fr":"Que venez-vous faire en Chine ? Combien de temps comptez-vous rester ?"},"explanation":{"en":"These questions combine 来…做什么 (purpose of visit) and 停留多久 (length of stay).","fr":"Ces questions combinent 来…做什么 (motif du séjour) et 停留多久 (durée du séjour)."},"audio":"/audio/self-intro/line-04.mp3"},{"id":"self-intro-line-05","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"我是来旅游的，大概两个星期。","pinyin":"Wǒ shì lái lǚyóu de, dàgài liǎng gè xīngqī.","translation":{"en":"I am here for tourism, about two weeks.","fr":"Je viens pour le tourisme, environ deux semaines."},"explanation":{"en":"我是来…的 is the key pattern for stating your purpose. Choose a simple word like 旅游 and a round number.","fr":"我是来…的 est la structure clé pour indiquer le motif. Choisis un mot simple comme 旅游 et un nombre rond."},"audio":"/audio/self-intro/line-05.mp3"},{"id":"self-intro-line-06","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"请问行李提取处在哪里？","pinyin":"Qǐngwèn xíngli tíqǔchù zài nǎlǐ?","translation":{"en":"Excuse me, where is baggage claim?","fr":"Excusez-moi, où se trouve la zone de récupération des bagages ?"},"explanation":{"en":"请问…在哪里？ is the main airport navigation pattern in this lesson.","fr":"请问…在哪里？ est la structure principale pour s’orienter dans l’aéroport."},"audio":"/audio/self-intro/line-06.mp3"},{"id":"self-intro-line-07","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"我的行李还没到。请问问询台在哪里？","pinyin":"Wǒ de xíngli hái méi dào. Qǐngwèn wènxúntái zài nǎlǐ?","translation":{"en":"My luggage has not arrived yet. Where is the information desk?","fr":"Mon bagage n’est pas encore arrivé. Où se trouve le bureau d’information ?"},"explanation":{"en":"Use 还没到 for something expected but not here yet, then ask where to get help.","fr":"Utilise 还没到 pour quelque chose d’attendu mais pas encore arrivé, puis demande où obtenir de l’aide."},"audio":"/audio/self-intro/line-07.mp3"},{"id":"self-intro-line-08","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"请问出口在哪里？请问出租车在哪里？","pinyin":"Qǐngwèn chūkǒu zài nǎlǐ? Qǐngwèn chūzūchē zài nǎlǐ?","translation":{"en":"Excuse me, where is the exit? Where are the taxis?","fr":"Excusez-moi, où est la sortie ? Où sont les taxis ?"},"explanation":{"en":"After baggage, the next useful steps are finding the exit and the taxi area.","fr":"Après les bagages, les étapes utiles sont de trouver la sortie puis la zone des taxis."},"audio":"/audio/self-intro/line-08.mp3"},{"id":"self-intro-line-09","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"我想去这个地址。请到这里。","pinyin":"Wǒ xiǎng qù zhège dìzhǐ. Qǐng dào zhèlǐ.","translation":{"en":"I want to go to this address. Please go here.","fr":"Je voudrais aller à cette adresse. Allez ici, s’il vous plaît."},"explanation":{"en":"Point to a saved address and say this instead of explaining where you are staying.","fr":"Montre une adresse enregistrée et dis cela au lieu d’expliquer où tu loges."},"audio":"/audio/self-intro/line-09.mp3"},{"id":"self-intro-line-10","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"大概需要多久？大概多少钱？","pinyin":"Dàgài xūyào duōjiǔ? Dàgài duōshǎo qián?","translation":{"en":"About how long will it take? About how much will it cost?","fr":"Cela prend environ combien de temps ? Cela coûte environ combien ?"},"explanation":{"en":"大概 softens the question when you only need an estimate before the ride starts.","fr":"大概 adoucit la question quand tu veux seulement une estimation avant le trajet."},"audio":"/audio/self-intro/line-10.mp3"}]}', 'draft', 3, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(5, 'self-intro', 'sentencePatterns', '[{"id":"self-intro-pattern-1","pattern":"请问……在哪里？","meaning":{"en":"Excuse me, where is ...?","fr":"Excusez-moi, où est ... ?"},"example":"请问行李提取处在哪里？","audio":"/audio/self-intro/pattern-01.mp3","explanation":{"en":"Swap in 出口, 问询台, or 出租车 to ask for the next airport step.","fr":"Remplace par 出口, 问询台 ou 出租车 pour demander l’étape suivante à l’aéroport."}},{"id":"self-intro-pattern-2","pattern":"我想去……","meaning":{"en":"I want to go to ...","fr":"Je voudrais aller à ..."},"example":"我想去这个地址。","audio":"/audio/self-intro/pattern-02.mp3","explanation":{"en":"Use this with a map pin or written address when you get into a taxi.","fr":"Utilise cette phrase avec une adresse écrite ou un point sur la carte en montant dans un taxi."}},{"id":"self-intro-pattern-3","pattern":"大概……？","meaning":{"en":"About / roughly ...?","fr":"Environ ... ?"},"example":"大概需要多久？","audio":"/audio/self-intro/pattern-03.mp3","explanation":{"en":"Use 大概 before time or price questions when an estimate is enough.","fr":"Place 大概 avant les questions de temps ou de prix quand une estimation suffit."}},{"id":"self-intro-pattern-4","pattern":"我是来……的。","meaning":{"en":"I came to ... / I am here to ...","fr":"Je suis venu(e) pour ..."},"example":"我是来旅游的。","audio":"/audio/self-intro/pattern-04.mp3","explanation":{"en":"Use this at a counter when asked about your visit purpose. Swap 旅游 for 出差 (business) or 学习 (study).","fr":"Utilise cette structure au guichet quand on te demande le motif de ta visite. Remplace 旅游 par 出差 (affaires) ou 学习 (études)."}},{"id":"self-intro-pattern-5","pattern":"我打算……","meaning":{"en":"I plan to ...","fr":"Je compte / J''ai l''intention de ..."},"example":"我打算停留两个星期。","audio":"/audio/self-intro/pattern-05.mp3","explanation":{"en":"Use 我打算 followed by a verb and duration to state your plan at immigration or a hotel desk.","fr":"Utilise 我打算 suivi d''un verbe et d''une durée pour indiquer ton projet à l''immigration ou à la réception."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(6, 'self-intro', 'sentencePatterns', '[{"id":"self-intro-pattern-1","pattern":"请问……在哪里？","meaning":{"en":"Excuse me, where is ...?","fr":"Excusez-moi, où est ... ?"},"example":"请问行李提取处在哪里？","audio":"/audio/self-intro/pattern-01.mp3","explanation":{"en":"Swap in 出口, 问询台, or 出租车 to ask for the next airport step.","fr":"Remplace par 出口, 问询台 ou 出租车 pour demander l’étape suivante à l’aéroport."}},{"id":"self-intro-pattern-2","pattern":"我想去……","meaning":{"en":"I want to go to ...","fr":"Je voudrais aller à ..."},"example":"我想去这个地址。","audio":"/audio/self-intro/pattern-02.mp3","explanation":{"en":"Use this with a map pin or written address when you get into a taxi.","fr":"Utilise cette phrase avec une adresse écrite ou un point sur la carte en montant dans un taxi."}},{"id":"self-intro-pattern-3","pattern":"大概……？","meaning":{"en":"About / roughly ...?","fr":"Environ ... ?"},"example":"大概需要多久？","audio":"/audio/self-intro/pattern-03.mp3","explanation":{"en":"Use 大概 before time or price questions when an estimate is enough.","fr":"Place 大概 avant les questions de temps ou de prix quand une estimation suffit."}},{"id":"self-intro-pattern-4","pattern":"我是来……的。","meaning":{"en":"I came to ... / I am here to ...","fr":"Je suis venu(e) pour ..."},"example":"我是来旅游的。","audio":"/audio/self-intro/pattern-04.mp3","explanation":{"en":"Use this at a counter when asked about your visit purpose. Swap 旅游 for 出差 (business) or 学习 (study).","fr":"Utilise cette structure au guichet quand on te demande le motif de ta visite. Remplace 旅游 par 出差 (affaires) ou 学习 (études)."}},{"id":"self-intro-pattern-5","pattern":"我打算……","meaning":{"en":"I plan to ...","fr":"Je compte / J''ai l''intention de ..."},"example":"我打算停留两个星期。","audio":"/audio/self-intro/pattern-05.mp3","explanation":{"en":"Use 我打算 followed by a verb and duration to state your plan at immigration or a hotel desk.","fr":"Utilise 我打算 suivi d''un verbe et d''une durée pour indiquer ton projet à l''immigration ou à la réception."}}]', 'draft', 5, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(7, 'self-intro', 'vocabulary', '[{"id":"self-intro-vocab-1","hanzi":"护照","pinyin":"hùzhào","audio":"/audio/self-intro/vocab-01.mp3","meaning":{"en":"passport","fr":"passeport"},"explanation":{"en":"The key document word you may need at counters after landing.","fr":"Le mot clé pour le document que l’on peut demander aux guichets après l’arrivée."}},{"id":"self-intro-vocab-2","hanzi":"行李提取处","pinyin":"xíngli tíqǔchù","audio":"/audio/self-intro/vocab-02.mp3","meaning":{"en":"baggage claim","fr":"récupération des bagages"},"explanation":{"en":"Look for this after leaving the arrival corridor.","fr":"Cherche cet endroit après le couloir d’arrivée."}},{"id":"self-intro-vocab-3","hanzi":"问询台","pinyin":"wènxúntái","audio":"/audio/self-intro/vocab-03.mp3","meaning":{"en":"information desk","fr":"bureau d’information"},"explanation":{"en":"A useful place to ask when luggage is delayed or directions are unclear.","fr":"Un endroit utile si les bagages tardent ou si le chemin n’est pas clair."}},{"id":"self-intro-vocab-4","hanzi":"出租车","pinyin":"chūzūchē","audio":"/audio/self-intro/vocab-04.mp3","meaning":{"en":"taxi","fr":"taxi"},"explanation":{"en":"Use it when asking for the taxi stand or pickup area.","fr":"Utilise ce mot pour demander la station ou la zone de prise en charge des taxis."}},{"id":"self-intro-vocab-5","hanzi":"地址","pinyin":"dìzhǐ","audio":"/audio/self-intro/vocab-05.mp3","meaning":{"en":"address","fr":"adresse"},"explanation":{"en":"Show the saved address and keep the spoken Chinese simple.","fr":"Montre l’adresse enregistrée et garde la phrase chinoise simple."}},{"id":"self-intro-vocab-6","hanzi":"海关","pinyin":"hǎiguān","audio":"/audio/self-intro/vocab-06.mp3","meaning":{"en":"customs","fr":"douane"},"explanation":{"en":"Look for 海关 signs after baggage claim before exiting the airport.","fr":"Cherche les panneaux 海关 après la récupération des bagages avant de sortir."}},{"id":"self-intro-vocab-7","hanzi":"入境","pinyin":"rùjìng","audio":"/audio/self-intro/vocab-07.mp3","meaning":{"en":"entry / immigration","fr":"entrée / immigration"},"explanation":{"en":"入境 is the border control step you go through after landing.","fr":"入境 est l''étape du contrôle aux frontières après l''atterrissage."}},{"id":"self-intro-vocab-8","hanzi":"旅游","pinyin":"lǚyóu","audio":"/audio/self-intro/vocab-08.mp3","meaning":{"en":"tourism / travel","fr":"tourisme / voyage"},"explanation":{"en":"The simplest answer when asked 来中国做什么 at immigration.","fr":"La réponse la plus simple quand on te demande 来中国做什么 à l''immigration."}},{"id":"self-intro-vocab-9","hanzi":"停留","pinyin":"tíngliú","audio":"/audio/self-intro/vocab-09.mp3","meaning":{"en":"stay / stop over","fr":"séjourner / faire escale"},"explanation":{"en":"停留多久 is how an officer or hotel clerk asks about your length of stay.","fr":"停留多久 est la façon dont un agent ou un réceptionniste demande la durée du séjour."}},{"id":"self-intro-vocab-10","hanzi":"星期","pinyin":"xīngqī","audio":"/audio/self-intro/vocab-10.mp3","meaning":{"en":"week","fr":"semaine"},"explanation":{"en":"Use this after a number to state how many weeks you will stay.","fr":"Utilise ce mot après un nombre pour indiquer combien de semaines tu restes."}},{"id":"self-intro-vocab-11","hanzi":"指纹","pinyin":"zhǐwén","audio":"/audio/self-intro/vocab-11.mp3","meaning":{"en":"fingerprint","fr":"empreinte digitale"},"explanation":{"en":"You may hear this word at immigration when they ask you to scan your fingerprints.","fr":"Tu pourrais entendre ce mot à l''immigration quand on te demande de scanner tes empreintes."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
