(17, 'self-intro', 'shortInput', '{"id":"self-intro-short-input-01","prompt":{"en":"Ask where the exit is.","fr":"Demande où est la sortie."},"target":"请问出口在哪里？","explanation":{"en":"Use the same 请问…在哪里？ pattern after baggage claim.","fr":"Utilise la même structure 请问…在哪里？ après les bagages."},"audio":"/audio/self-intro/short-input-01.mp3"}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(18, 'self-intro', 'shortInput', '{"id":"self-intro-short-input-01","prompt":{"en":"Ask where the exit is.","fr":"Demande où est la sortie."},"target":"请问出口在哪里？","explanation":{"en":"Use the same 请问…在哪里？ pattern after baggage claim.","fr":"Utilise la même structure 请问…在哪里？ après les bagages."},"audio":"/audio/self-intro/short-input-01.mp3"}', 'draft', 17, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(19, 'ask-directions', 'lessonMeta', '{"id":"ask-directions","title":{"en":"Take a taxi to your hotel","fr":"Prendre un taxi jusqu’à son hôtel"},"scenario":{"en":"Get into a taxi, show the address, and ask roughly how long the ride will take.","fr":"Monter dans un taxi, montrer l’adresse et demander environ combien de temps prendra le trajet."}}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(20, 'ask-directions', 'lessonMeta', '{"id":"ask-directions","title":{"en":"Take a taxi to your hotel","fr":"Prendre un taxi jusqu’à son hôtel"},"scenario":{"en":"Get into a taxi, show the address, and ask roughly how long the ride will take.","fr":"Monter dans un taxi, montrer l’adresse et demander environ combien de temps prendra le trajet."}}', 'draft', 19, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(21, 'ask-directions', 'dialogue', '{"title":{"en":"Tell the driver your destination","fr":"Indiquer sa destination au chauffeur"},"lines":[{"id":"ask-directions-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"师傅，去这个酒店。","pinyin":"Shīfu, qù zhège jiǔdiàn.","translation":{"en":"Driver, please go to this hotel.","fr":"Chauffeur, allez à cet hôtel, s’il vous plaît."},"explanation":{"en":"师傅 is a practical way to address a taxi driver politely.","fr":"师傅 est une façon pratique et polie de s’adresser à un chauffeur."},"audio":"/audio/ask-directions/line-01.mp3"},{"id":"ask-directions-line-02","speaker":{"en":"Driver","fr":"Chauffeur"},"hanzi":"好的，你给我看一下地址。","pinyin":"Hǎo de, nǐ gěi wǒ kàn yíxià dìzhǐ.","translation":{"en":"Okay, show me the address.","fr":"D’accord, montre-moi l’adresse."},"explanation":{"en":"给我看一下 is useful when the driver wants to see your phone or booking address.","fr":"给我看一下 est utile quand le chauffeur veut voir l’adresse sur ton téléphone ou ta réservation."},"audio":"/audio/ask-directions/line-02.mp3"},{"id":"ask-directions-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"在这里。","pinyin":"Zài zhèlǐ.","translation":{"en":"It is here.","fr":"C’est ici."},"explanation":{"en":"Use 在这里 while pointing to the address on your phone.","fr":"Utilise 在这里 en montrant l’adresse sur ton téléphone."},"audio":"/audio/ask-directions/line-03.mp3"},{"id":"ask-directions-line-04","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"大概多久到？","pinyin":"Dàgài duōjiǔ dào?","translation":{"en":"About how long until we arrive?","fr":"Environ combien de temps pour arriver ?"},"explanation":{"en":"大概多久到 is a short way to ask the approximate travel time.","fr":"大概多久到 est une façon courte de demander la durée approximative du trajet."},"audio":"/audio/ask-directions/line-04.mp3"},{"id":"ask-directions-line-05","speaker":{"en":"Driver","fr":"Chauffeur"},"hanzi":"四十分钟左右。","pinyin":"Sìshí fēnzhōng zuǒyòu.","translation":{"en":"Around forty minutes.","fr":"Environ quarante minutes."},"explanation":{"en":"左右 means around or about, useful with time and price estimates.","fr":"左右 signifie environ ; c’est utile pour les durées et les prix approximatifs."},"audio":"/audio/ask-directions/line-05.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
