(37, 'order-food', 'lessonMeta', '{"id":"order-food","title":{"en":"Hotel or apartment check-in","fr":"Arrivée à l’hôtel ou à l’appartement"},"scenario":{"en":"Complete the simplest front desk check-in: say you have a reservation, give your name, show your passport, and receive the room card.","fr":"Effectuer le check-in le plus simple à la réception : dire que l’on a une réservation, donner son nom, présenter son passeport et recevoir la carte de chambre."}}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(38, 'order-food', 'lessonMeta', '{"id":"order-food","title":{"en":"Hotel or apartment check-in","fr":"Arrivée à l’hôtel ou à l’appartement"},"scenario":{"en":"Complete the simplest front desk check-in: say you have a reservation, give your name, show your passport, and receive the room card.","fr":"Effectuer le check-in le plus simple à la réception : dire que l’on a une réservation, donner son nom, présenter son passeport et recevoir la carte de chambre."}}', 'draft', 37, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(39, 'order-food', 'dialogue', '{"title":{"en":"Check in at the front desk","fr":"Faire le check-in à la réception"},"lines":[{"id":"order-food-line-01","speaker":{"en":"Guest","fr":"Client"},"hanzi":"你好，我有预订。","pinyin":"Nǐ hǎo, wǒ yǒu yùdìng.","translation":{"en":"Hello, I have a reservation.","fr":"Bonjour, j’ai une réservation."},"explanation":{"en":"我有预订 is the fastest way to start hotel check-in.","fr":"我有预订 est la façon la plus rapide de commencer un check-in à l’hôtel."},"audio":"/audio/order-food/line-01.mp3"},{"id":"order-food-line-02","speaker":{"en":"Front desk","fr":"Réception"},"hanzi":"请问您叫什么名字？","pinyin":"Qǐngwèn nín jiào shénme míngzi?","translation":{"en":"May I ask your name?","fr":"Puis-je vous demander votre nom ?"},"explanation":{"en":"The front desk uses 您 for polite “you” when checking the reservation.","fr":"La réception utilise 您, un « vous » poli, pour vérifier la réservation."},"audio":"/audio/order-food/line-02.mp3"},{"id":"order-food-line-03","speaker":{"en":"Guest","fr":"Client"},"hanzi":"我叫 Alex。","pinyin":"Wǒ jiào Alex.","translation":{"en":"My name is Alex.","fr":"Je m’appelle Alex."},"explanation":{"en":"Keep only the name pattern here because the situation is a front desk check-in.","fr":"On garde seulement la structure du nom ici, car le contexte est la réception."},"audio":"/audio/order-food/line-03.mp3"},{"id":"order-food-line-04","speaker":{"en":"Front desk","fr":"Réception"},"hanzi":"请出示护照。","pinyin":"Qǐng chūshì hùzhào.","translation":{"en":"Please show your passport.","fr":"Veuillez présenter votre passeport."},"explanation":{"en":"Hotels commonly ask for a passport during check-in.","fr":"Les hôtels demandent souvent le passeport pendant le check-in."},"audio":"/audio/order-food/line-04.mp3"},{"id":"order-food-line-05","speaker":{"en":"Front desk","fr":"Réception"},"hanzi":"好的，这是您的房卡。","pinyin":"Hǎo de, zhè shì nín de fángkǎ.","translation":{"en":"Okay, this is your room card.","fr":"D’accord, voici votre carte de chambre."},"explanation":{"en":"房卡 is the room card you need after check-in.","fr":"房卡 est la carte de chambre nécessaire après le check-in."},"audio":"/audio/order-food/line-05.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
