(45, 'order-food', 'pronunciation', '[{"id":"order-food-pronunciation-1","focus":{"en":"Name pattern in a front desk context","fr":"Structure du nom à la réception"},"audioText":"我叫","audio":"/audio/order-food/pronunciation-01.mp3","tip":{"en":"Say 我叫 plus your name clearly; keep the focus on the booking, not a social self-introduction.","fr":"Dis clairement 我叫 suivi de ton nom ; le contexte reste la réservation, pas une présentation sociale."},"explanation":{"en":"This keeps the old name skill but moves it into the check-in task.","fr":"Cela garde la compétence du nom, mais la déplace dans la tâche de check-in."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
