(47, 'order-food', 'hanziRecognition', '[{"id":"order-food-hanzi-1","hanzi":"预","pinyin":"yù","meaning":{"en":"in advance; first character of reservation","fr":"à l’avance ; premier caractère de réservation"},"explanation":{"en":"Recognize 预 as part of 预订.","fr":"Reconnais 预 dans 预订."}},{"id":"order-food-hanzi-2","hanzi":"订","pinyin":"dìng","meaning":{"en":"book / reserve; second character of reservation","fr":"réserver ; deuxième caractère de réservation"},"explanation":{"en":"订 completes 预订, the word for reservation.","fr":"订 complète 预订, le mot pour réservation."}},{"id":"order-food-hanzi-3","hanzi":"房","pinyin":"fáng","meaning":{"en":"room / house","fr":"chambre / maison"},"explanation":{"en":"房 appears in 房卡, the room card.","fr":"房 apparaît dans 房卡, la carte de chambre."}},{"id":"order-food-hanzi-4","hanzi":"卡","pinyin":"kǎ","meaning":{"en":"card","fr":"carte"},"explanation":{"en":"卡 completes 房卡, the card for your room.","fr":"卡 complète 房卡, la carte de chambre."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
