(49, 'order-food', 'practice', '{"listening":[{"id":"order-food-listening-1","prompt":{"en":"Which phrase starts a hotel check-in?","fr":"Quelle phrase commence un check-in à l’hôtel ?"},"target":"你好，我有预订。","audio":"/audio/order-food/practice-listening-01.mp3","explanation":{"en":"This tells the front desk to look for your booking.","fr":"Cette phrase indique à la réception de chercher ta réservation."}}],"speaking":[{"id":"order-food-speaking-1","prompt":{"en":"Answer the front desk when they ask your name.","fr":"Réponds à la réception quand on te demande ton nom."},"target":"我叫 Alex。","audio":"/audio/order-food/practice-speaking-01.mp3","explanation":{"en":"Use 我叫 plus the booking name.","fr":"Utilise 我叫 suivi du nom de la réservation."}}],"reading":[{"id":"order-food-reading-1","prompt":{"en":"Match the item you receive after check-in.","fr":"Associe l’objet reçu après le check-in."},"target":"房卡","audio":"/audio/order-food/practice-reading-01.mp3","explanation":{"en":"房卡 is the room card for entering the hotel room.","fr":"房卡 est la carte pour entrer dans la chambre d’hôtel."}}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
