(57, 'phone-and-payment', 'dialogue', '{"title":{"en":"Ask about phone and payment setup","fr":"Demander de l’aide pour le téléphone et le paiement"},"lines":[{"id":"phone-and-payment-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"你好，我想办一张手机卡。","pinyin":"Nǐ hǎo, wǒ xiǎng bàn yì zhāng shǒujīkǎ.","translation":{"en":"Hello, I would like to get a SIM card.","fr":"Bonjour, je voudrais prendre une carte SIM."},"explanation":{"en":"我想办一张手机卡 keeps the request short and practical after check-in.","fr":"我想办一张手机卡 garde la demande courte et pratique après l’arrivée au logement."},"audio":"/audio/phone-and-payment/line-01.mp3"},{"id":"phone-and-payment-line-02","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"好的，请出示护照。","pinyin":"Hǎo de, qǐng chūshì hùzhào.","translation":{"en":"Okay, please show your passport.","fr":"D’accord, veuillez présenter votre passeport."},"explanation":{"en":"This reuses the passport phrase from arrival in a phone setup context.","fr":"Cette phrase réutilise le mot passeport dans un contexte de téléphone."},"audio":"/audio/phone-and-payment/line-02.mp3"},{"id":"phone-and-payment-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"这个号码可以用来支付吗？","pinyin":"Zhège hàomǎ kěyǐ yòng lái zhīfù ma?","translation":{"en":"Can this number be used for payment?","fr":"Est-ce que ce numéro peut servir au paiement ?"},"explanation":{"en":"The learner hears 手机号码 and 支付 as a simple setup question, not a full payment guide.","fr":"L’apprenant entend 手机号码 et 支付 dans une question simple, sans guide complet de paiement."},"audio":"/audio/phone-and-payment/line-03.mp3"},{"id":"phone-and-payment-line-04","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"可以，也可以先用现金。","pinyin":"Kěyǐ, yě kěyǐ xiān yòng xiànjīn.","translation":{"en":"Yes, and you can also use cash first.","fr":"Oui, et vous pouvez aussi utiliser des espèces d’abord."},"explanation":{"en":"现金 gives a safe fallback word if phone payment is not ready yet.","fr":"现金 donne un mot de secours si le paiement mobile n’est pas encore prêt."},"audio":"/audio/phone-and-payment/line-04.mp3"},{"id":"phone-and-payment-line-05","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"好的，谢谢。","pinyin":"Hǎo de, xièxie.","translation":{"en":"Okay, thank you.","fr":"D’accord, merci."},"explanation":{"en":"A short closing phrase keeps the exchange beginner friendly.","fr":"Une formule de clôture courte garde l’échange accessible aux débutants."},"audio":"/audio/phone-and-payment/line-05.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
