(59, 'phone-and-payment', 'sentencePatterns', '[{"id":"phone-and-payment-pattern-1","pattern":"我想办……","meaning":{"en":"I would like to get / arrange ...","fr":"Je voudrais obtenir / faire ..."},"example":"我想办一张手机卡。","audio":"/audio/phone-and-payment/pattern-01.mp3","explanation":{"en":"Use it for a compact service request at a counter.","fr":"Utilise cette structure pour une demande simple au comptoir."}},{"id":"phone-and-payment-pattern-2","pattern":"可以用……吗？","meaning":{"en":"Can I use ...?","fr":"Puis-je utiliser ... ?"},"example":"可以用手机支付吗？","audio":"/audio/phone-and-payment/pattern-02.mp3","explanation":{"en":"This is the shortest useful question for checking a payment method.","fr":"C’est la question utile la plus courte pour vérifier un moyen de paiement."}},{"id":"phone-and-payment-pattern-3","pattern":"也可以先……","meaning":{"en":"It is also possible to first ...","fr":"Il est aussi possible de d’abord ..."},"example":"也可以先用现金。","audio":"/audio/phone-and-payment/pattern-03.mp3","explanation":{"en":"This pattern introduces a fallback without adding complex payment details.","fr":"Cette structure introduit une solution de secours sans détails de paiement complexes."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(60, 'phone-and-payment', 'sentencePatterns', '[{"id":"phone-and-payment-pattern-1","pattern":"我想办……","meaning":{"en":"I would like to get / arrange ...","fr":"Je voudrais obtenir / faire ..."},"example":"我想办一张手机卡。","audio":"/audio/phone-and-payment/pattern-01.mp3","explanation":{"en":"Use it for a compact service request at a counter.","fr":"Utilise cette structure pour une demande simple au comptoir."}},{"id":"phone-and-payment-pattern-2","pattern":"可以用……吗？","meaning":{"en":"Can I use ...?","fr":"Puis-je utiliser ... ?"},"example":"可以用手机支付吗？","audio":"/audio/phone-and-payment/pattern-02.mp3","explanation":{"en":"This is the shortest useful question for checking a payment method.","fr":"C’est la question utile la plus courte pour vérifier un moyen de paiement."}},{"id":"phone-and-payment-pattern-3","pattern":"也可以先……","meaning":{"en":"It is also possible to first ...","fr":"Il est aussi possible de d’abord ..."},"example":"也可以先用现金。","audio":"/audio/phone-and-payment/pattern-03.mp3","explanation":{"en":"This pattern introduces a fallback without adding complex payment details.","fr":"Cette structure introduit une solution de secours sans détails de paiement complexes."}}]', 'draft', 59, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(61, 'phone-and-payment', 'vocabulary', '[{"id":"phone-and-payment-vocab-1","hanzi":"手机卡","pinyin":"shǒujīkǎ","audio":"/audio/phone-and-payment/vocab-01.mp3","meaning":{"en":"SIM card / phone card","fr":"carte SIM / carte de téléphone"},"explanation":{"en":"The practical word for asking about phone service after arrival.","fr":"Le mot pratique pour demander un service téléphonique après l’arrivée."}},{"id":"phone-and-payment-vocab-2","hanzi":"手机号码","pinyin":"shǒujī hàomǎ","audio":"/audio/phone-and-payment/vocab-02.mp3","meaning":{"en":"phone number","fr":"numéro de téléphone"},"explanation":{"en":"Recognize it when someone confirms the number attached to the phone.","fr":"Reconnais-le quand quelqu’un confirme le numéro lié au téléphone."}},{"id":"phone-and-payment-vocab-3","hanzi":"支付","pinyin":"zhīfù","audio":"/audio/phone-and-payment/vocab-03.mp3","meaning":{"en":"pay / payment","fr":"payer / paiement"},"explanation":{"en":"A core word for mobile payment questions.","fr":"Un mot central pour les questions de paiement mobile."}},{"id":"phone-and-payment-vocab-4","hanzi":"现金","pinyin":"xiànjīn","audio":"/audio/phone-and-payment/vocab-04.mp3","meaning":{"en":"cash","fr":"espèces"},"explanation":{"en":"A useful fallback if phone payment is not ready.","fr":"Une solution utile si le paiement mobile n’est pas prêt."}},{"id":"phone-and-payment-vocab-5","hanzi":"可以","pinyin":"kěyǐ","audio":"/audio/phone-and-payment/vocab-05.mp3","meaning":{"en":"can / may","fr":"pouvoir / être possible"},"explanation":{"en":"Use it to ask if an action or payment method is possible.","fr":"Utilise-le pour demander si une action ou un moyen de paiement est possible."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
