(63, 'phone-and-payment', 'pronunciation', '[{"id":"phone-and-payment-pronunciation-1","focus":{"en":"Phone and payment words","fr":"Mots du téléphone et du paiement"},"audioText":"手机，支付，现金","audio":"/audio/phone-and-payment/pronunciation-01.mp3","tip":{"en":"Keep 手机, 支付, and 现金 short and clear; they carry the key meaning in this setup exchange.","fr":"Prononce clairement 手机, 支付 et 现金 ; ce sont les mots clés de cet échange."},"explanation":{"en":"This lesson prioritizes recognizing the useful service words over technical setup detail.","fr":"Cette leçon vise la reconnaissance de mots de service utiles, pas les détails techniques."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(64, 'phone-and-payment', 'pronunciation', '[{"id":"phone-and-payment-pronunciation-1","focus":{"en":"Phone and payment words","fr":"Mots du téléphone et du paiement"},"audioText":"手机，支付，现金","audio":"/audio/phone-and-payment/pronunciation-01.mp3","tip":{"en":"Keep 手机, 支付, and 现金 short and clear; they carry the key meaning in this setup exchange.","fr":"Prononce clairement 手机, 支付 et 现金 ; ce sont les mots clés de cet échange."},"explanation":{"en":"This lesson prioritizes recognizing the useful service words over technical setup detail.","fr":"Cette leçon vise la reconnaissance de mots de service utiles, pas les détails techniques."}}]', 'draft', 63, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(65, 'phone-and-payment', 'hanziRecognition', '[{"id":"phone-and-payment-hanzi-1","hanzi":"手","pinyin":"shǒu","meaning":{"en":"hand; first character of mobile phone","fr":"main ; premier caractère de téléphone portable"},"explanation":{"en":"Recognize 手 inside 手机.","fr":"Reconnais 手 dans 手机."}},{"id":"phone-and-payment-hanzi-2","hanzi":"机","pinyin":"jī","meaning":{"en":"machine; second character of mobile phone","fr":"machine ; deuxième caractère de téléphone portable"},"explanation":{"en":"机 completes 手机, the common word for mobile phone.","fr":"机 complète 手机, le mot courant pour téléphone portable."}},{"id":"phone-and-payment-hanzi-3","hanzi":"支","pinyin":"zhī","meaning":{"en":"support; first character of payment","fr":"soutenir ; premier caractère de paiement"},"explanation":{"en":"Recognize 支 at the start of 支付.","fr":"Reconnais 支 au début de 支付."}},{"id":"phone-and-payment-hanzi-4","hanzi":"付","pinyin":"fù","meaning":{"en":"pay; second character of payment","fr":"payer ; deuxième caractère de paiement"},"explanation":{"en":"付 completes 支付, the word for payment.","fr":"付 complète 支付, le mot pour paiement."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
