(75, 'convenience-store-run', 'dialogue', '{"title":{"en":"Buy one simple item","fr":"Acheter un article simple"},"lines":[{"id":"convenience-store-run-line-01","speaker":{"en":"Customer","fr":"Client"},"hanzi":"你好，我要一瓶水。","pinyin":"Nǐ hǎo, wǒ yào yì píng shuǐ.","translation":{"en":"Hello, I want a bottle of water.","fr":"Bonjour, je voudrais une bouteille d’eau."},"explanation":{"en":"我要一瓶水 is a direct beginner phrase for a first convenience store purchase.","fr":"我要一瓶水 est une phrase directe pour un premier achat en supérette."},"audio":"/audio/convenience-store-run/line-01.mp3"},{"id":"convenience-store-run-line-02","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"好的，还要别的吗？","pinyin":"Hǎo de, hái yào bié de ma?","translation":{"en":"Okay, do you want anything else?","fr":"D’accord, vous voulez autre chose ?"},"explanation":{"en":"还要别的吗 is a common checkout question after you name one item.","fr":"还要别的吗 est une question courante à la caisse après avoir nommé un article."},"audio":"/audio/convenience-store-run/line-02.mp3"},{"id":"convenience-store-run-line-03","speaker":{"en":"Customer","fr":"Client"},"hanzi":"不要了，一共多少钱？","pinyin":"Bú yào le, yígòng duōshao qián?","translation":{"en":"No more, how much is it altogether?","fr":"Rien d’autre, ça fait combien au total ?"},"explanation":{"en":"不要了 closes the shopping list, and 一共多少钱 asks the total price.","fr":"不要了 ferme la liste d’achats, et 一共多少钱 demande le prix total."},"audio":"/audio/convenience-store-run/line-03.mp3"},{"id":"convenience-store-run-line-04","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"五块钱。","pinyin":"Wǔ kuài qián.","translation":{"en":"Five yuan.","fr":"Cinq yuans."},"explanation":{"en":"块 is the everyday word you will hear for yuan in small purchases.","fr":"块 est le mot courant que tu entendras pour yuan dans les petits achats."},"audio":"/audio/convenience-store-run/line-04.mp3"},{"id":"convenience-store-run-line-05","speaker":{"en":"Customer","fr":"Client"},"hanzi":"可以用手机支付吗？","pinyin":"Kěyǐ yòng shǒujī zhīfù ma?","translation":{"en":"Can I pay by phone?","fr":"Puis-je payer avec mon téléphone ?"},"explanation":{"en":"This reuses the phone payment question from the previous lesson in a store.","fr":"Cette phrase réutilise la question de paiement mobile de la leçon précédente dans un magasin."},"audio":"/audio/convenience-store-run/line-05.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
