(81, 'convenience-store-run', 'pronunciation', '[{"id":"convenience-store-run-pronunciation-1","focus":{"en":"Short checkout phrases","fr":"Phrases courtes à la caisse"},"audioText":"一瓶水，不要了，多少钱","audio":"/audio/convenience-store-run/pronunciation-01.mp3","tip":{"en":"Keep 一瓶水, 不要了, and 多少钱 short; each phrase can stand alone at checkout.","fr":"Garde 一瓶水, 不要了 et 多少钱 courts ; chaque phrase fonctionne seule à la caisse."},"explanation":{"en":"This first store lesson favors clear survival phrases over a long shopping conversation.","fr":"Cette première leçon de supérette privilégie des phrases de survie claires plutôt qu’une longue conversation."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(82, 'convenience-store-run', 'pronunciation', '[{"id":"convenience-store-run-pronunciation-1","focus":{"en":"Short checkout phrases","fr":"Phrases courtes à la caisse"},"audioText":"一瓶水，不要了，多少钱","audio":"/audio/convenience-store-run/pronunciation-01.mp3","tip":{"en":"Keep 一瓶水, 不要了, and 多少钱 short; each phrase can stand alone at checkout.","fr":"Garde 一瓶水, 不要了 et 多少钱 courts ; chaque phrase fonctionne seule à la caisse."},"explanation":{"en":"This first store lesson favors clear survival phrases over a long shopping conversation.","fr":"Cette première leçon de supérette privilégie des phrases de survie claires plutôt qu’une longue conversation."}}]', 'draft', 81, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(83, 'convenience-store-run', 'hanziRecognition', '[{"id":"convenience-store-run-hanzi-1","hanzi":"水","pinyin":"shuǐ","meaning":{"en":"water","fr":"eau"},"explanation":{"en":"Recognize 水 when buying a bottle of water.","fr":"Reconnais 水 quand tu achètes une bouteille d’eau."}},{"id":"convenience-store-run-hanzi-2","hanzi":"钱","pinyin":"qián","meaning":{"en":"money","fr":"argent"},"explanation":{"en":"钱 appears in the price question 多少钱.","fr":"钱 apparaît dans la question de prix 多少钱."}},{"id":"convenience-store-run-hanzi-3","hanzi":"要","pinyin":"yào","meaning":{"en":"want / need","fr":"vouloir / avoir besoin"},"explanation":{"en":"要 appears in both 我要 and 不要了.","fr":"要 apparaît dans 我要 et 不要了."}},{"id":"convenience-store-run-hanzi-4","hanzi":"瓶","pinyin":"píng","meaning":{"en":"bottle","fr":"bouteille"},"explanation":{"en":"瓶 is the measure word for a bottle in 一瓶水.","fr":"瓶 est le classificateur pour une bouteille dans 一瓶水."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
