(85, 'convenience-store-run', 'practice', '{"listening":[{"id":"convenience-store-run-listening-1","prompt":{"en":"Listen for the phrase that means a bottle of water.","fr":"Écoute la phrase qui signifie une bouteille d’eau."},"target":"一瓶水","audio":"/audio/convenience-store-run/practice-listening-01.mp3","explanation":{"en":"一瓶水 is the item you are buying.","fr":"一瓶水 est l’article que tu achètes."}}],"speaking":[{"id":"convenience-store-run-speaking-1","prompt":{"en":"Say you do not need anything else.","fr":"Dis que tu n’as besoin de rien d’autre."},"target":"不要了。","audio":"/audio/convenience-store-run/practice-speaking-01.mp3","explanation":{"en":"不要了 answers the clerk’s “anything else?” question.","fr":"不要了 répond à la question « autre chose ? » de l’employé."}}],"reading":[{"id":"convenience-store-run-reading-1","prompt":{"en":"Choose the phrase for asking the total price.","fr":"Choisis la phrase pour demander le prix total."},"target":"一共多少钱？","audio":"/audio/convenience-store-run/practice-reading-01.mp3","explanation":{"en":"一共多少钱？ asks how much the purchase costs altogether.","fr":"一共多少钱？ demande combien coûte l’achat au total."}}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
