(111, 'metro-ticket', 'dialogue', '{"title":{"en":"Ask for a route and ticket","fr":"Demander un itinéraire et un ticket"},"lines":[{"id":"metro-ticket-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"去人民广场怎么走？","pinyin":"Qù Rénmín Guǎngchǎng zěnme zǒu?","translation":{"en":"How do I get to People’s Square?","fr":"Comment aller à la Place du Peuple ?"},"explanation":{"en":"去……怎么走 is the basic route question for a station or place.","fr":"去……怎么走 est la question de base pour demander un itinéraire vers une station ou un lieu."},"audio":"/audio/metro-ticket/line-01.mp3"},{"id":"metro-ticket-line-02","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"坐二号线。","pinyin":"Zuò èr hào xiàn.","translation":{"en":"Take line two.","fr":"Prenez la ligne 2."},"explanation":{"en":"号线 names the numbered metro line.","fr":"号线 indique la ligne de métro numérotée."},"audio":"/audio/metro-ticket/line-02.mp3"},{"id":"metro-ticket-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"我要一张去人民广场的票。","pinyin":"Wǒ yào yì zhāng qù Rénmín Guǎngchǎng de piào.","translation":{"en":"I want one ticket to People’s Square.","fr":"Je voudrais un ticket pour la Place du Peuple."},"explanation":{"en":"一张 is the measure word for one ticket.","fr":"一张 est le classificateur pour un ticket."},"audio":"/audio/metro-ticket/line-03.mp3"},{"id":"metro-ticket-line-04","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"要几站？","pinyin":"Yào jǐ zhàn?","translation":{"en":"How many stops does it take?","fr":"Combien de stations faut-il ?"},"explanation":{"en":"要几站 is short and useful when you are counting stops.","fr":"要几站 est court et utile pour compter les stations."},"audio":"/audio/metro-ticket/line-04.mp3"},{"id":"metro-ticket-line-05","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"三站。","pinyin":"Sān zhàn.","translation":{"en":"Three stops.","fr":"Trois stations."},"explanation":{"en":"Listen for a number plus 站 when someone answers.","fr":"Écoute un nombre suivi de 站 quand quelqu’un répond."},"audio":"/audio/metro-ticket/line-05.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
