(117, 'metro-ticket', 'pronunciation', '[{"id":"metro-ticket-pronunciation-1","focus":{"en":"Numbers with lines and stops","fr":"Nombres avec lignes et stations"},"audioText":"二号线，三站，一张票","audio":"/audio/metro-ticket/pronunciation-01.mp3","tip":{"en":"Keep the number clear before 号线 and 站 so the route is not confused.","fr":"Garde le nombre clair devant 号线 et 站 pour éviter de confondre l’itinéraire."},"explanation":{"en":"Metro answers often compress to a number plus line or stops.","fr":"Les réponses dans le métro se réduisent souvent à un nombre plus une ligne ou des stations."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(118, 'metro-ticket', 'pronunciation', '[{"id":"metro-ticket-pronunciation-1","focus":{"en":"Numbers with lines and stops","fr":"Nombres avec lignes et stations"},"audioText":"二号线，三站，一张票","audio":"/audio/metro-ticket/pronunciation-01.mp3","tip":{"en":"Keep the number clear before 号线 and 站 so the route is not confused.","fr":"Garde le nombre clair devant 号线 et 站 pour éviter de confondre l’itinéraire."},"explanation":{"en":"Metro answers often compress to a number plus line or stops.","fr":"Les réponses dans le métro se réduisent souvent à un nombre plus une ligne ou des stations."}}]', 'draft', 117, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(119, 'metro-ticket', 'hanziRecognition', '[{"id":"metro-ticket-hanzi-1","hanzi":"地","pinyin":"dì","meaning":{"en":"ground / earth","fr":"sol / terre"},"explanation":{"en":"It appears in 地铁.","fr":"Il apparaît dans 地铁."}},{"id":"metro-ticket-hanzi-2","hanzi":"铁","pinyin":"tiě","meaning":{"en":"iron","fr":"fer"},"explanation":{"en":"Together with 地 it forms 地铁, metro.","fr":"Avec 地, il forme 地铁, métro."}},{"id":"metro-ticket-hanzi-3","hanzi":"票","pinyin":"piào","meaning":{"en":"ticket","fr":"ticket"},"explanation":{"en":"Look for it when buying a fare.","fr":"Repère-le pour acheter un trajet."}},{"id":"metro-ticket-hanzi-4","hanzi":"站","pinyin":"zhàn","meaning":{"en":"station","fr":"station"},"explanation":{"en":"It marks stops and station names.","fr":"Il indique les arrêts et les noms de station."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
