(121, 'metro-ticket', 'practice', '{"listening":[{"id":"metro-ticket-listening-1","prompt":{"en":"Listen for the metro ticket to People''s Square.","fr":"Écoute le ticket de métro pour la Place du Peuple."},"target":"我要一张去人民广场的票。","audio":"/audio/metro-ticket/practice-listening-01.mp3","explanation":{"en":"The destination sits between 去 and 的票.","fr":"La destination se place entre 去 et 的票."}}],"speaking":[{"id":"metro-ticket-speaking-1","prompt":{"en":"Ask how to get to People’s Square.","fr":"Demande comment aller à la Place du Peuple."},"target":"去人民广场怎么走？","audio":"/audio/metro-ticket/practice-speaking-01.mp3","explanation":{"en":"This is the route question before the ticket request.","fr":"C’est la question d’itinéraire avant la demande de ticket."}}],"reading":[{"id":"metro-ticket-reading-1","prompt":{"en":"Read the short stop-count question.","fr":"Lis la question courte sur le nombre de stations."},"target":"要几站？","audio":"/audio/metro-ticket/practice-reading-01.mp3","explanation":{"en":"This phrase helps you track how far the ride is.","fr":"Cette phrase aide à suivre la distance du trajet."}}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
