(127, 'pharmacy-help', 'lessonMeta', '{"id":"pharmacy-help","title":{"en":"Ask for help at a pharmacy","fr":"Demander de l’aide à la pharmacie"},"scenario":{"en":"Tell a pharmacy clerk you have a headache, answer whether you have a fever, understand medicine frequency, and ask the price.","fr":"Dire au pharmacien que tu as mal à la tête, répondre si tu as de la fièvre, comprendre la fréquence du médicament et demander le prix."}}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(128, 'pharmacy-help', 'lessonMeta', '{"id":"pharmacy-help","title":{"en":"Ask for help at a pharmacy","fr":"Demander de l’aide à la pharmacie"},"scenario":{"en":"Tell a pharmacy clerk you have a headache, answer whether you have a fever, understand medicine frequency, and ask the price.","fr":"Dire au pharmacien que tu as mal à la tête, répondre si tu as de la fièvre, comprendre la fréquence du médicament et demander le prix."}}', 'draft', 127, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(129, 'pharmacy-help', 'dialogue', '{"title":{"en":"Describe a mild symptom","fr":"Décrire un symptôme léger"},"lines":[{"id":"pharmacy-help-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"你好，我头疼。","pinyin":"Nǐ hǎo, wǒ tóu téng.","translation":{"en":"Hello, my head hurts.","fr":"Bonjour, j’ai mal à la tête."},"explanation":{"en":"我……疼 is a simple way to name a mild pain.","fr":"我……疼 est une façon simple de nommer une douleur légère."},"audio":"/audio/pharmacy-help/line-01.mp3"},{"id":"pharmacy-help-line-02","speaker":{"en":"Pharmacist","fr":"Pharmacien"},"hanzi":"你发烧吗？","pinyin":"Nǐ fāshāo ma?","translation":{"en":"Do you have a fever?","fr":"Avez-vous de la fièvre ?"},"explanation":{"en":"The clerk asks a yes/no symptom question with 吗.","fr":"Le pharmacien pose une question oui/non sur un symptôme avec 吗."},"audio":"/audio/pharmacy-help/line-02.mp3"},{"id":"pharmacy-help-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"不发烧。","pinyin":"Bù fāshāo.","translation":{"en":"No fever.","fr":"Pas de fièvre."},"explanation":{"en":"A short negative answer is enough for this beginner exchange.","fr":"Une réponse négative courte suffit pour cet échange débutant."},"audio":"/audio/pharmacy-help/line-03.mp3"},{"id":"pharmacy-help-line-04","speaker":{"en":"Pharmacist","fr":"Pharmacien"},"hanzi":"这个药，一天两次。","pinyin":"Zhège yào, yì tiān liǎng cì.","translation":{"en":"This medicine, twice a day.","fr":"Ce médicament, deux fois par jour."},"explanation":{"en":"一天两次 gives the frequency without complex medical wording.","fr":"一天两次 donne la fréquence sans vocabulaire médical complexe."},"audio":"/audio/pharmacy-help/line-04.mp3"},{"id":"pharmacy-help-line-05","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"多少钱？谢谢。","pinyin":"Duōshao qián? Xièxie.","translation":{"en":"How much is it? Thank you.","fr":"Combien ça coûte ? Merci."},"explanation":{"en":"The price question closes the pharmacy interaction politely.","fr":"La question du prix termine poliment l’échange à la pharmacie."},"audio":"/audio/pharmacy-help/line-05.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(130, 'pharmacy-help', 'dialogue', '{"title":{"en":"Describe a mild symptom","fr":"Décrire un symptôme léger"},"lines":[{"id":"pharmacy-help-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"你好，我头疼。","pinyin":"Nǐ hǎo, wǒ tóu téng.","translation":{"en":"Hello, my head hurts.","fr":"Bonjour, j’ai mal à la tête."},"explanation":{"en":"我……疼 is a simple way to name a mild pain.","fr":"我……疼 est une façon simple de nommer une douleur légère."},"audio":"/audio/pharmacy-help/line-01.mp3"},{"id":"pharmacy-help-line-02","speaker":{"en":"Pharmacist","fr":"Pharmacien"},"hanzi":"你发烧吗？","pinyin":"Nǐ fāshāo ma?","translation":{"en":"Do you have a fever?","fr":"Avez-vous de la fièvre ?"},"explanation":{"en":"The clerk asks a yes/no symptom question with 吗.","fr":"Le pharmacien pose une question oui/non sur un symptôme avec 吗."},"audio":"/audio/pharmacy-help/line-02.mp3"},{"id":"pharmacy-help-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"不发烧。","pinyin":"Bù fāshāo.","translation":{"en":"No fever.","fr":"Pas de fièvre."},"explanation":{"en":"A short negative answer is enough for this beginner exchange.","fr":"Une réponse négative courte suffit pour cet échange débutant."},"audio":"/audio/pharmacy-help/line-03.mp3"},{"id":"pharmacy-help-line-04","speaker":{"en":"Pharmacist","fr":"Pharmacien"},"hanzi":"这个药，一天两次。","pinyin":"Zhège yào, yì tiān liǎng cì.","translation":{"en":"This medicine, twice a day.","fr":"Ce médicament, deux fois par jour."},"explanation":{"en":"一天两次 gives the frequency without complex medical wording.","fr":"一天两次 donne la fréquence sans vocabulaire médical complexe."},"audio":"/audio/pharmacy-help/line-04.mp3"},{"id":"pharmacy-help-line-05","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"多少钱？谢谢。","pinyin":"Duōshao qián? Xièxie.","translation":{"en":"How much is it? Thank you.","fr":"Combien ça coûte ? Merci."},"explanation":{"en":"The price question closes the pharmacy interaction politely.","fr":"La question du prix termine poliment l’échange à la pharmacie."},"audio":"/audio/pharmacy-help/line-05.mp3"}]}', 'draft', 129, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(131, 'pharmacy-help', 'sentencePatterns', '[{"id":"pharmacy-help-pattern-1","pattern":"我……疼。","meaning":{"en":"My ... hurts.","fr":"J’ai mal à ..."},"example":"我头疼。","audio":"/audio/pharmacy-help/pattern-01.mp3","explanation":{"en":"Put the body part before 疼 for a simple symptom.","fr":"Place la partie du corps avant 疼 pour un symptôme simple."}},{"id":"pharmacy-help-pattern-2","pattern":"你……吗？","meaning":{"en":"Do you ...?","fr":"Est-ce que vous ... ?"},"example":"你发烧吗？","audio":"/audio/pharmacy-help/pattern-02.mp3","explanation":{"en":"Listen for 吗 when a clerk asks a yes/no health question.","fr":"Écoute 吗 quand un employé pose une question de santé oui/non."}},{"id":"pharmacy-help-pattern-3","pattern":"一天……次。","meaning":{"en":"... times a day.","fr":"... fois par jour."},"example":"一天两次。","audio":"/audio/pharmacy-help/pattern-03.mp3","explanation":{"en":"This common dosing phrase appears on instructions and in speech.","fr":"Cette phrase de dosage courante apparaît dans les consignes et à l’oral."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(132, 'pharmacy-help', 'sentencePatterns', '[{"id":"pharmacy-help-pattern-1","pattern":"我……疼。","meaning":{"en":"My ... hurts.","fr":"J’ai mal à ..."},"example":"我头疼。","audio":"/audio/pharmacy-help/pattern-01.mp3","explanation":{"en":"Put the body part before 疼 for a simple symptom.","fr":"Place la partie du corps avant 疼 pour un symptôme simple."}},{"id":"pharmacy-help-pattern-2","pattern":"你……吗？","meaning":{"en":"Do you ...?","fr":"Est-ce que vous ... ?"},"example":"你发烧吗？","audio":"/audio/pharmacy-help/pattern-02.mp3","explanation":{"en":"Listen for 吗 when a clerk asks a yes/no health question.","fr":"Écoute 吗 quand un employé pose une question de santé oui/non."}},{"id":"pharmacy-help-pattern-3","pattern":"一天……次。","meaning":{"en":"... times a day.","fr":"... fois par jour."},"example":"一天两次。","audio":"/audio/pharmacy-help/pattern-03.mp3","explanation":{"en":"This common dosing phrase appears on instructions and in speech.","fr":"Cette phrase de dosage courante apparaît dans les consignes et à l’oral."}}]', 'draft', 131, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(133, 'pharmacy-help', 'vocabulary', '[{"id":"pharmacy-help-vocab-1","hanzi":"药店","pinyin":"yàodiàn","audio":"/audio/pharmacy-help/vocab-01.mp3","meaning":{"en":"pharmacy","fr":"pharmacie"},"explanation":{"en":"The place to ask for simple medicine help.","fr":"Le lieu pour demander une aide simple avec un médicament."}},{"id":"pharmacy-help-vocab-2","hanzi":"药","pinyin":"yào","audio":"/audio/pharmacy-help/vocab-02.mp3","meaning":{"en":"medicine","fr":"médicament"},"explanation":{"en":"A core word in pharmacy instructions.","fr":"Un mot essentiel dans les consignes de pharmacie."}},{"id":"pharmacy-help-vocab-3","hanzi":"头疼","pinyin":"tóu téng","audio":"/audio/pharmacy-help/vocab-03.mp3","meaning":{"en":"headache","fr":"mal à la tête"},"explanation":{"en":"The mild symptom used in the dialogue.","fr":"Le symptôme léger utilisé dans le dialogue."}},{"id":"pharmacy-help-vocab-4","hanzi":"发烧","pinyin":"fāshāo","audio":"/audio/pharmacy-help/vocab-04.mp3","meaning":{"en":"to have a fever","fr":"avoir de la fièvre"},"explanation":{"en":"A common follow-up symptom question.","fr":"Une question de symptôme fréquente."}},{"id":"pharmacy-help-vocab-5","hanzi":"过敏","pinyin":"guòmǐn","audio":"/audio/pharmacy-help/vocab-05.mp3","meaning":{"en":"allergy / allergic","fr":"allergie / allergique"},"explanation":{"en":"A safety word to recognize even in a mild-health lesson.","fr":"Un mot de sécurité à reconnaître même dans une leçon de santé légère."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
