(135, 'pharmacy-help', 'pronunciation', '[{"id":"pharmacy-help-pronunciation-1","focus":{"en":"Short symptom words","fr":"Mots courts de symptômes"},"audioText":"头疼，发烧，不发烧，一天两次","audio":"/audio/pharmacy-help/pronunciation-01.mp3","tip":{"en":"Keep symptom words short and clear; repeat 不发烧 as one calm answer.","fr":"Garde les mots de symptômes courts et clairs ; répète 不发烧 comme une réponse calme."},"explanation":{"en":"Clarity matters more than speed in pharmacy phrases.","fr":"La clarté compte plus que la vitesse dans les phrases de pharmacie."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(136, 'pharmacy-help', 'pronunciation', '[{"id":"pharmacy-help-pronunciation-1","focus":{"en":"Short symptom words","fr":"Mots courts de symptômes"},"audioText":"头疼，发烧，不发烧，一天两次","audio":"/audio/pharmacy-help/pronunciation-01.mp3","tip":{"en":"Keep symptom words short and clear; repeat 不发烧 as one calm answer.","fr":"Garde les mots de symptômes courts et clairs ; répète 不发烧 comme une réponse calme."},"explanation":{"en":"Clarity matters more than speed in pharmacy phrases.","fr":"La clarté compte plus que la vitesse dans les phrases de pharmacie."}}]', 'draft', 135, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(137, 'pharmacy-help', 'hanziRecognition', '[{"id":"pharmacy-help-hanzi-1","hanzi":"药","pinyin":"yào","meaning":{"en":"medicine","fr":"médicament"},"explanation":{"en":"Recognize it in 药店 and 这个药.","fr":"Reconnais-le dans 药店 et 这个药."}},{"id":"pharmacy-help-hanzi-2","hanzi":"头","pinyin":"tóu","meaning":{"en":"head","fr":"tête"},"explanation":{"en":"It starts 头疼.","fr":"Il commence 头疼."}},{"id":"pharmacy-help-hanzi-3","hanzi":"疼","pinyin":"téng","meaning":{"en":"hurt / ache","fr":"faire mal"},"explanation":{"en":"Use it after a body part for pain.","fr":"Utilise-le après une partie du corps pour une douleur."}},{"id":"pharmacy-help-hanzi-4","hanzi":"烧","pinyin":"shāo","meaning":{"en":"fever / burn","fr":"fièvre / brûler"},"explanation":{"en":"It appears in 发烧.","fr":"Il apparaît dans 发烧."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(138, 'pharmacy-help', 'hanziRecognition', '[{"id":"pharmacy-help-hanzi-1","hanzi":"药","pinyin":"yào","meaning":{"en":"medicine","fr":"médicament"},"explanation":{"en":"Recognize it in 药店 and 这个药.","fr":"Reconnais-le dans 药店 et 这个药."}},{"id":"pharmacy-help-hanzi-2","hanzi":"头","pinyin":"tóu","meaning":{"en":"head","fr":"tête"},"explanation":{"en":"It starts 头疼.","fr":"Il commence 头疼."}},{"id":"pharmacy-help-hanzi-3","hanzi":"疼","pinyin":"téng","meaning":{"en":"hurt / ache","fr":"faire mal"},"explanation":{"en":"Use it after a body part for pain.","fr":"Utilise-le après une partie du corps pour une douleur."}},{"id":"pharmacy-help-hanzi-4","hanzi":"烧","pinyin":"shāo","meaning":{"en":"fever / burn","fr":"fièvre / brûler"},"explanation":{"en":"It appears in 发烧.","fr":"Il apparaît dans 发烧."}}]', 'draft', 137, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(139, 'pharmacy-help', 'practice', '{"listening":[{"id":"pharmacy-help-listening-1","prompt":{"en":"Listen for headache and no fever.","fr":"Écoute “mal à la tête” et “pas de fièvre”."},"target":"我头疼，不发烧。","audio":"/audio/pharmacy-help/practice-listening-01.mp3","explanation":{"en":"This combines the symptom and the negative fever answer.","fr":"Cela combine le symptôme et la réponse négative sur la fièvre."}}],"speaking":[{"id":"pharmacy-help-speaking-1","prompt":{"en":"Say that your head hurts.","fr":"Dis que tu as mal à la tête."},"target":"我头疼。","audio":"/audio/pharmacy-help/practice-speaking-01.mp3","explanation":{"en":"Start with the shortest clear symptom sentence.","fr":"Commence par la phrase de symptôme la plus courte et claire."}}],"reading":[{"id":"pharmacy-help-reading-1","prompt":{"en":"Read the medicine frequency phrase.","fr":"Lis la phrase de fréquence du médicament."},"target":"一天两次。","audio":"/audio/pharmacy-help/practice-reading-01.mp3","explanation":{"en":"Recognize how many times per day the medicine is used.","fr":"Reconnais combien de fois par jour le médicament est utilisé."}}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(140, 'pharmacy-help', 'practice', '{"listening":[{"id":"pharmacy-help-listening-1","prompt":{"en":"Listen for headache and no fever.","fr":"Écoute “mal à la tête” et “pas de fièvre”."},"target":"我头疼，不发烧。","audio":"/audio/pharmacy-help/practice-listening-01.mp3","explanation":{"en":"This combines the symptom and the negative fever answer.","fr":"Cela combine le symptôme et la réponse négative sur la fièvre."}}],"speaking":[{"id":"pharmacy-help-speaking-1","prompt":{"en":"Say that your head hurts.","fr":"Dis que tu as mal à la tête."},"target":"我头疼。","audio":"/audio/pharmacy-help/practice-speaking-01.mp3","explanation":{"en":"Start with the shortest clear symptom sentence.","fr":"Commence par la phrase de symptôme la plus courte et claire."}}],"reading":[{"id":"pharmacy-help-reading-1","prompt":{"en":"Read the medicine frequency phrase.","fr":"Lis la phrase de fréquence du médicament."},"target":"一天两次。","audio":"/audio/pharmacy-help/practice-reading-01.mp3","explanation":{"en":"Recognize how many times per day the medicine is used.","fr":"Reconnais combien de fois par jour le médicament est utilisé."}}]}', 'draft', 139, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(141, 'pharmacy-help', 'reviewCards', '[{"id":"pharmacy-help-review-1","front":"药店","back":{"en":"pharmacy","fr":"pharmacie"},"explanation":{"en":"The place for the help request.","fr":"Le lieu de la demande d’aide."}},{"id":"pharmacy-help-review-2","front":"头疼","back":{"en":"headache","fr":"mal à la tête"},"explanation":{"en":"Say 我头疼 to report it.","fr":"Dis 我头疼 pour le signaler."}},{"id":"pharmacy-help-review-3","front":"一天两次","back":{"en":"twice a day","fr":"deux fois par jour"},"explanation":{"en":"A common medicine frequency.","fr":"Une fréquence courante pour un médicament."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(142, 'pharmacy-help', 'reviewCards', '[{"id":"pharmacy-help-review-1","front":"药店","back":{"en":"pharmacy","fr":"pharmacie"},"explanation":{"en":"The place for the help request.","fr":"Le lieu de la demande d’aide."}},{"id":"pharmacy-help-review-2","front":"头疼","back":{"en":"headache","fr":"mal à la tête"},"explanation":{"en":"Say 我头疼 to report it.","fr":"Dis 我头疼 pour le signaler."}},{"id":"pharmacy-help-review-3","front":"一天两次","back":{"en":"twice a day","fr":"deux fois par jour"},"explanation":{"en":"A common medicine frequency.","fr":"Une fréquence courante pour un médicament."}}]', 'draft', 141, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(143, 'pharmacy-help', 'shortInput', '{"id":"pharmacy-help-short-input-01","prompt":{"en":"Say that your head hurts and you do not have a fever.","fr":"Dis que tu as mal à la tête et pas de fièvre."},"target":"我头疼，不发烧。","explanation":{"en":"This gives a mild symptom and a clear no-fever answer.","fr":"Cela donne un symptôme léger et une réponse claire sans fièvre."},"audio":"/audio/pharmacy-help/short-input-01.mp3"}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(144, 'pharmacy-help', 'shortInput', '{"id":"pharmacy-help-short-input-01","prompt":{"en":"Say that your head hurts and you do not have a fever.","fr":"Dis que tu as mal à la tête et pas de fièvre."},"target":"我头疼，不发烧。","explanation":{"en":"This gives a mild symptom and a clear no-fever answer.","fr":"Cela donne un symptôme léger et une réponse claire sans fièvre."},"audio":"/audio/pharmacy-help/short-input-01.mp3"}', 'draft', 143, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(145, 'ask-for-help-problem', 'lessonMeta', '{"id":"ask-for-help-problem","title":{"en":"Ask for help with a problem","fr":"Demander de l’aide pour un problème"},"scenario":{"en":"Ask politely for help, explain that your phone has a payment problem, and ask the other person to speak more slowly.","fr":"Demander poliment de l’aide, expliquer que ton téléphone a un problème de paiement et demander à l’autre personne de parler plus lentement."}}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(146, 'ask-for-help-problem', 'lessonMeta', '{"id":"ask-for-help-problem","title":{"en":"Ask for help with a problem","fr":"Demander de l’aide pour un problème"},"scenario":{"en":"Ask politely for help, explain that your phone has a payment problem, and ask the other person to speak more slowly.","fr":"Demander poliment de l’aide, expliquer que ton téléphone a un problème de paiement et demander à l’autre personne de parler plus lentement."}}', 'draft', 145, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(147, 'ask-for-help-problem', 'dialogue', '{"title":{"en":"Get help with a phone payment problem","fr":"Obtenir de l’aide pour un problème de paiement mobile"},"lines":[{"id":"ask-for-help-problem-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"你好，可以帮我一下吗？","pinyin":"Nǐ hǎo, kěyǐ bāng wǒ yíxià ma?","translation":{"en":"Hello, could you help me for a moment?","fr":"Bonjour, pouvez-vous m’aider un instant ?"},"explanation":{"en":"可以帮我一下吗 is polite and short when you need help.","fr":"可以帮我一下吗 est poli et court quand tu as besoin d’aide."},"audio":"/audio/ask-for-help-problem/line-01.mp3"},{"id":"ask-for-help-problem-line-02","speaker":{"en":"Helper","fr":"Aide"},"hanzi":"怎么了？","pinyin":"Zěnme le?","translation":{"en":"What happened?","fr":"Qu’est-ce qui se passe ?"},"explanation":{"en":"This common question invites you to explain the problem.","fr":"Cette question courante t’invite à expliquer le problème."},"audio":"/audio/ask-for-help-problem/line-02.mp3"},{"id":"ask-for-help-problem-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"我的手机有问题，不能支付。","pinyin":"Wǒ de shǒujī yǒu wèntí, bù néng zhīfù.","translation":{"en":"My phone has a problem and cannot pay.","fr":"Mon téléphone a un problème et ne peut pas payer."},"explanation":{"en":"我的……有问题 names the item; 不能支付 names the payment issue.","fr":"我的……有问题 nomme l’objet ; 不能支付 nomme le problème de paiement."},"audio":"/audio/ask-for-help-problem/line-03.mp3"},{"id":"ask-for-help-problem-line-04","speaker":{"en":"Helper","fr":"Aide"},"hanzi":"我帮你看一下。","pinyin":"Wǒ bāng nǐ kàn yíxià.","translation":{"en":"I’ll help you take a look.","fr":"Je vais regarder pour vous aider."},"explanation":{"en":"看一下 signals a quick check, not a long technical conversation.","fr":"看一下 indique une vérification rapide, pas une longue conversation technique."},"audio":"/audio/ask-for-help-problem/line-04.mp3"},{"id":"ask-for-help-problem-line-05","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"请慢一点说，谢谢。","pinyin":"Qǐng màn yìdiǎn shuō, xièxie.","translation":{"en":"Please speak a little more slowly, thank you.","fr":"Parlez un peu plus lentement, s’il vous plaît. Merci."},"explanation":{"en":"请慢一点说 helps when the helper answers too quickly.","fr":"请慢一点说 aide quand la personne répond trop vite."},"audio":"/audio/ask-for-help-problem/line-05.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
