(153, 'ask-for-help-problem', 'pronunciation', '[{"id":"ask-for-help-problem-pronunciation-1","focus":{"en":"Stress in urgent short phrases","fr":"Accent dans les phrases courtes urgentes"},"audioText":"帮我一下，有问题，不能支付，请慢一点说","audio":"/audio/ask-for-help-problem/pronunciation-01.mp3","tip":{"en":"Keep each chunk calm and separated so the request sounds polite, not panicked.","fr":"Garde chaque morceau calme et séparé pour que la demande reste polie, pas paniquée."},"explanation":{"en":"Problem phrases work best when they are short and easy to repeat.","fr":"Les phrases de problème fonctionnent mieux quand elles sont courtes et faciles à répéter."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(154, 'ask-for-help-problem', 'pronunciation', '[{"id":"ask-for-help-problem-pronunciation-1","focus":{"en":"Stress in urgent short phrases","fr":"Accent dans les phrases courtes urgentes"},"audioText":"帮我一下，有问题，不能支付，请慢一点说","audio":"/audio/ask-for-help-problem/pronunciation-01.mp3","tip":{"en":"Keep each chunk calm and separated so the request sounds polite, not panicked.","fr":"Garde chaque morceau calme et séparé pour que la demande reste polie, pas paniquée."},"explanation":{"en":"Problem phrases work best when they are short and easy to repeat.","fr":"Les phrases de problème fonctionnent mieux quand elles sont courtes et faciles à répéter."}}]', 'draft', 153, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(155, 'ask-for-help-problem', 'hanziRecognition', '[{"id":"ask-for-help-problem-hanzi-1","hanzi":"帮","pinyin":"bāng","meaning":{"en":"help","fr":"aider"},"explanation":{"en":"It starts 帮我一下.","fr":"Il commence 帮我一下."}},{"id":"ask-for-help-problem-hanzi-2","hanzi":"问","pinyin":"wèn","meaning":{"en":"ask","fr":"demander"},"explanation":{"en":"It is the first character of 问题.","fr":"C’est le premier caractère de 问题."}},{"id":"ask-for-help-problem-hanzi-3","hanzi":"题","pinyin":"tí","meaning":{"en":"topic / problem element","fr":"sujet / élément de problème"},"explanation":{"en":"It completes 问题.","fr":"Il complète 问题."}},{"id":"ask-for-help-problem-hanzi-4","hanzi":"慢","pinyin":"màn","meaning":{"en":"slow","fr":"lent"},"explanation":{"en":"Use it in 慢一点 to ask for slower speech.","fr":"Utilise-le dans 慢一点 pour demander une parole plus lente."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(156, 'ask-for-help-problem', 'hanziRecognition', '[{"id":"ask-for-help-problem-hanzi-1","hanzi":"帮","pinyin":"bāng","meaning":{"en":"help","fr":"aider"},"explanation":{"en":"It starts 帮我一下.","fr":"Il commence 帮我一下."}},{"id":"ask-for-help-problem-hanzi-2","hanzi":"问","pinyin":"wèn","meaning":{"en":"ask","fr":"demander"},"explanation":{"en":"It is the first character of 问题.","fr":"C’est le premier caractère de 问题."}},{"id":"ask-for-help-problem-hanzi-3","hanzi":"题","pinyin":"tí","meaning":{"en":"topic / problem element","fr":"sujet / élément de problème"},"explanation":{"en":"It completes 问题.","fr":"Il complète 问题."}},{"id":"ask-for-help-problem-hanzi-4","hanzi":"慢","pinyin":"màn","meaning":{"en":"slow","fr":"lent"},"explanation":{"en":"Use it in 慢一点 to ask for slower speech.","fr":"Utilise-le dans 慢一点 pour demander une parole plus lente."}}]', 'draft', 155, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(157, 'ask-for-help-problem', 'practice', '{"listening":[{"id":"ask-for-help-problem-listening-1","prompt":{"en":"Listen for the sentence that says the phone has a problem.","fr":"Écoute la phrase qui dit que le téléphone a un problème."},"target":"我的手机有问题，不能支付。","audio":"/audio/ask-for-help-problem/practice-listening-01.mp3","explanation":{"en":"This is the key explanation after asking for help.","fr":"C’est l’explication clé après la demande d’aide."}}],"speaking":[{"id":"ask-for-help-problem-speaking-1","prompt":{"en":"Ask someone to help you for a moment.","fr":"Demande à quelqu’un de t’aider un instant."},"target":"可以帮我一下吗？","audio":"/audio/ask-for-help-problem/practice-speaking-01.mp3","explanation":{"en":"Open with the polite request before explaining the issue.","fr":"Commence par la demande polie avant d’expliquer le problème."}}],"reading":[{"id":"ask-for-help-problem-reading-1","prompt":{"en":"Read the slower-speech request.","fr":"Lis la demande de parler plus lentement."},"target":"请慢一点说。","audio":"/audio/ask-for-help-problem/practice-reading-01.mp3","explanation":{"en":"This helps you keep the conversation understandable.","fr":"Cela t’aide à garder la conversation compréhensible."}}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
