(159, 'ask-for-help-problem', 'reviewCards', '[{"id":"ask-for-help-problem-review-1","front":"帮我一下","back":{"en":"help me for a moment","fr":"aidez-moi un instant"},"explanation":{"en":"A polite core help request.","fr":"Une demande d’aide centrale et polie."}},{"id":"ask-for-help-problem-review-2","front":"有问题","back":{"en":"has a problem","fr":"a un problème"},"explanation":{"en":"Use it after the item with the issue.","fr":"Utilise-le après l’objet qui pose problème."}},{"id":"ask-for-help-problem-review-3","front":"慢一点","back":{"en":"a little slower","fr":"un peu plus lentement"},"explanation":{"en":"A repair phrase when speech is too fast.","fr":"Une phrase de réparation si la parole est trop rapide."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
