(161, 'ask-for-help-problem', 'shortInput', '{"id":"ask-for-help-problem-short-input-01","prompt":{"en":"Ask someone to help you.","fr":"Demande à quelqu’un de t’aider."},"target":"可以帮我一下吗？","explanation":{"en":"This opens the problem-solving exchange politely.","fr":"Cela ouvre l’échange de résolution de problème poliment."},"audio":"/audio/ask-for-help-problem/short-input-01.mp3"}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(162, 'ask-for-help-problem', 'shortInput', '{"id":"ask-for-help-problem-short-input-01","prompt":{"en":"Ask someone to help you.","fr":"Demande à quelqu’un de t’aider."},"target":"可以帮我一下吗？","explanation":{"en":"This opens the problem-solving exchange politely.","fr":"Cela ouvre l’échange de résolution de problème poliment."},"audio":"/audio/ask-for-help-problem/short-input-01.mp3"}', 'draft', 161, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(163, 'train-station-ticket', 'lessonMeta', '{"id":"train-station-ticket","title":{"en":"Buy a train station ticket","fr":"Acheter un billet en gare"},"scenario":{"en":"Buy a train ticket to Shanghai, choose today or tomorrow, understand a departure time, and show your passport.","fr":"Acheter un billet de train pour Shanghai, choisir aujourd’hui ou demain, comprendre l’heure de départ et présenter son passeport."}}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(164, 'train-station-ticket', 'lessonMeta', '{"id":"train-station-ticket","title":{"en":"Buy a train station ticket","fr":"Acheter un billet en gare"},"scenario":{"en":"Buy a train ticket to Shanghai, choose today or tomorrow, understand a departure time, and show your passport.","fr":"Acheter un billet de train pour Shanghai, choisir aujourd’hui ou demain, comprendre l’heure de départ et présenter son passeport."}}', 'draft', 163, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(165, 'train-station-ticket', 'dialogue', '{"title":{"en":"Buy a same-day train ticket","fr":"Acheter un billet de train pour aujourd’hui"},"lines":[{"id":"train-station-ticket-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"你好，我想买一张去上海的票。","pinyin":"Nǐ hǎo, wǒ xiǎng mǎi yì zhāng qù Shànghǎi de piào.","translation":{"en":"Hello, I would like to buy one ticket to Shanghai.","fr":"Bonjour, je voudrais acheter un billet pour Shanghai."},"explanation":{"en":"This capstone ticket phrase extends the metro ticket pattern with 我想买.","fr":"Cette phrase de billet finale prolonge le modèle du ticket de métro avec 我想买."},"audio":"/audio/train-station-ticket/line-01.mp3"},{"id":"train-station-ticket-line-02","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"今天还是明天？","pinyin":"Jīntiān háishi míngtiān?","translation":{"en":"Today or tomorrow?","fr":"Aujourd’hui ou demain ?"},"explanation":{"en":"还是 presents two choices in a question.","fr":"还是 présente deux choix dans une question."},"audio":"/audio/train-station-ticket/line-02.mp3"},{"id":"train-station-ticket-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"今天下午。","pinyin":"Jīntiān xiàwǔ.","translation":{"en":"This afternoon.","fr":"Cet après-midi."},"explanation":{"en":"A short time answer is enough for a first train ticket purchase.","fr":"Une réponse courte de temps suffit pour un premier achat de billet de train."},"audio":"/audio/train-station-ticket/line-03.mp3"},{"id":"train-station-ticket-line-04","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"请出示护照。","pinyin":"Qǐng chūshì hùzhào.","translation":{"en":"Please show your passport.","fr":"Veuillez présenter votre passeport."},"explanation":{"en":"Train tickets may require the same passport phrase learned earlier.","fr":"Les billets de train peuvent demander la même phrase du passeport apprise plus tôt."},"audio":"/audio/train-station-ticket/line-04.mp3"},{"id":"train-station-ticket-line-05","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"这是您的票，三点出发。","pinyin":"Zhè shì nín de piào, sān diǎn chūfā.","translation":{"en":"This is your ticket; it departs at three o’clock.","fr":"Voici votre billet ; il part à trois heures."},"explanation":{"en":"三点出发 gives the key departure time in a compact phrase.","fr":"三点出发 donne l’heure de départ clé dans une phrase compacte."},"audio":"/audio/train-station-ticket/line-05.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(166, 'train-station-ticket', 'dialogue', '{"title":{"en":"Buy a same-day train ticket","fr":"Acheter un billet de train pour aujourd’hui"},"lines":[{"id":"train-station-ticket-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"你好，我想买一张去上海的票。","pinyin":"Nǐ hǎo, wǒ xiǎng mǎi yì zhāng qù Shànghǎi de piào.","translation":{"en":"Hello, I would like to buy one ticket to Shanghai.","fr":"Bonjour, je voudrais acheter un billet pour Shanghai."},"explanation":{"en":"This capstone ticket phrase extends the metro ticket pattern with 我想买.","fr":"Cette phrase de billet finale prolonge le modèle du ticket de métro avec 我想买."},"audio":"/audio/train-station-ticket/line-01.mp3"},{"id":"train-station-ticket-line-02","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"今天还是明天？","pinyin":"Jīntiān háishi míngtiān?","translation":{"en":"Today or tomorrow?","fr":"Aujourd’hui ou demain ?"},"explanation":{"en":"还是 presents two choices in a question.","fr":"还是 présente deux choix dans une question."},"audio":"/audio/train-station-ticket/line-02.mp3"},{"id":"train-station-ticket-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"今天下午。","pinyin":"Jīntiān xiàwǔ.","translation":{"en":"This afternoon.","fr":"Cet après-midi."},"explanation":{"en":"A short time answer is enough for a first train ticket purchase.","fr":"Une réponse courte de temps suffit pour un premier achat de billet de train."},"audio":"/audio/train-station-ticket/line-03.mp3"},{"id":"train-station-ticket-line-04","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"请出示护照。","pinyin":"Qǐng chūshì hùzhào.","translation":{"en":"Please show your passport.","fr":"Veuillez présenter votre passeport."},"explanation":{"en":"Train tickets may require the same passport phrase learned earlier.","fr":"Les billets de train peuvent demander la même phrase du passeport apprise plus tôt."},"audio":"/audio/train-station-ticket/line-04.mp3"},{"id":"train-station-ticket-line-05","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"这是您的票，三点出发。","pinyin":"Zhè shì nín de piào, sān diǎn chūfā.","translation":{"en":"This is your ticket; it departs at three o’clock.","fr":"Voici votre billet ; il part à trois heures."},"explanation":{"en":"三点出发 gives the key departure time in a compact phrase.","fr":"三点出发 donne l’heure de départ clé dans une phrase compacte."},"audio":"/audio/train-station-ticket/line-05.mp3"}]}', 'draft', 165, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(167, 'train-station-ticket', 'sentencePatterns', '[{"id":"train-station-ticket-pattern-1","pattern":"我想买一张去……的票。","meaning":{"en":"I would like to buy one ticket to ...","fr":"Je voudrais acheter un billet pour ..."},"example":"我想买一张去上海的票。","audio":"/audio/train-station-ticket/pattern-01.mp3","explanation":{"en":"Use this at a ticket counter with the destination in the middle.","fr":"Utilise cette phrase au guichet avec la destination au milieu."}},{"id":"train-station-ticket-pattern-2","pattern":"今天还是明天？","meaning":{"en":"Today or tomorrow?","fr":"Aujourd’hui ou demain ?"},"example":"今天还是明天？","audio":"/audio/train-station-ticket/pattern-02.mp3","explanation":{"en":"This choice question helps you answer the travel date.","fr":"Cette question de choix t’aide à répondre sur la date de trajet."}},{"id":"train-station-ticket-pattern-3","pattern":"……点出发。","meaning":{"en":"Departs at ... o’clock.","fr":"Départ à ... heures."},"example":"三点出发。","audio":"/audio/train-station-ticket/pattern-03.mp3","explanation":{"en":"Listen for a time before 出发 to catch the departure.","fr":"Écoute l’heure avant 出发 pour saisir le départ."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(168, 'train-station-ticket', 'sentencePatterns', '[{"id":"train-station-ticket-pattern-1","pattern":"我想买一张去……的票。","meaning":{"en":"I would like to buy one ticket to ...","fr":"Je voudrais acheter un billet pour ..."},"example":"我想买一张去上海的票。","audio":"/audio/train-station-ticket/pattern-01.mp3","explanation":{"en":"Use this at a ticket counter with the destination in the middle.","fr":"Utilise cette phrase au guichet avec la destination au milieu."}},{"id":"train-station-ticket-pattern-2","pattern":"今天还是明天？","meaning":{"en":"Today or tomorrow?","fr":"Aujourd’hui ou demain ?"},"example":"今天还是明天？","audio":"/audio/train-station-ticket/pattern-02.mp3","explanation":{"en":"This choice question helps you answer the travel date.","fr":"Cette question de choix t’aide à répondre sur la date de trajet."}},{"id":"train-station-ticket-pattern-3","pattern":"……点出发。","meaning":{"en":"Departs at ... o’clock.","fr":"Départ à ... heures."},"example":"三点出发。","audio":"/audio/train-station-ticket/pattern-03.mp3","explanation":{"en":"Listen for a time before 出发 to catch the departure.","fr":"Écoute l’heure avant 出发 pour saisir le départ."}}]', 'draft', 167, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(169, 'train-station-ticket', 'vocabulary', '[{"id":"train-station-ticket-vocab-1","hanzi":"火车站","pinyin":"huǒchēzhàn","audio":"/audio/train-station-ticket/vocab-01.mp3","meaning":{"en":"train station","fr":"gare"},"explanation":{"en":"The place for this capstone ticketing scene.","fr":"Le lieu de cette scène finale d’achat de billet."}},{"id":"train-station-ticket-vocab-2","hanzi":"车票","pinyin":"chēpiào","audio":"/audio/train-station-ticket/vocab-02.mp3","meaning":{"en":"train ticket / vehicle ticket","fr":"billet de train / ticket de transport"},"explanation":{"en":"A ticket word you will see at stations.","fr":"Un mot de billet que tu verras en gare."}},{"id":"train-station-ticket-vocab-3","hanzi":"上海","pinyin":"Shànghǎi","audio":"/audio/train-station-ticket/vocab-03.mp3","meaning":{"en":"Shanghai","fr":"Shanghai"},"explanation":{"en":"The model destination in the ticket request.","fr":"La destination modèle dans la demande de billet."}},{"id":"train-station-ticket-vocab-4","hanzi":"今天","pinyin":"jīntiān","audio":"/audio/train-station-ticket/vocab-04.mp3","meaning":{"en":"today","fr":"aujourd’hui"},"explanation":{"en":"The date answer paired with 明天.","fr":"La réponse de date associée à 明天."}},{"id":"train-station-ticket-vocab-5","hanzi":"出发","pinyin":"chūfā","audio":"/audio/train-station-ticket/vocab-05.mp3","meaning":{"en":"depart","fr":"partir / départ"},"explanation":{"en":"The action word for the train leaving.","fr":"Le mot d’action pour le départ du train."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
