(171, 'train-station-ticket', 'pronunciation', '[{"id":"train-station-ticket-pronunciation-1","focus":{"en":"Ticketing phrase linking","fr":"Enchaînement des phrases de billetterie"},"audioText":"我想买一张去上海的票，今天下午，三点出发","audio":"/audio/train-station-ticket/pronunciation-01.mp3","tip":{"en":"Group the destination phrase together, then pause before the date and time.","fr":"Groupe la destination, puis marque une pause avant la date et l’heure."},"explanation":{"en":"This final lesson links ticket, date, passport, and departure time.","fr":"Cette dernière leçon relie billet, date, passeport et heure de départ."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(172, 'train-station-ticket', 'pronunciation', '[{"id":"train-station-ticket-pronunciation-1","focus":{"en":"Ticketing phrase linking","fr":"Enchaînement des phrases de billetterie"},"audioText":"我想买一张去上海的票，今天下午，三点出发","audio":"/audio/train-station-ticket/pronunciation-01.mp3","tip":{"en":"Group the destination phrase together, then pause before the date and time.","fr":"Groupe la destination, puis marque une pause avant la date et l’heure."},"explanation":{"en":"This final lesson links ticket, date, passport, and departure time.","fr":"Cette dernière leçon relie billet, date, passeport et heure de départ."}}]', 'draft', 171, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(173, 'train-station-ticket', 'hanziRecognition', '[{"id":"train-station-ticket-hanzi-1","hanzi":"火","pinyin":"huǒ","meaning":{"en":"fire","fr":"feu"},"explanation":{"en":"It starts 火车, train.","fr":"Il commence 火车, train."}},{"id":"train-station-ticket-hanzi-2","hanzi":"车","pinyin":"chē","meaning":{"en":"vehicle / train in compounds","fr":"véhicule / train dans les mots composés"},"explanation":{"en":"It appears in 火车站 and 车票.","fr":"Il apparaît dans 火车站 et 车票."}},{"id":"train-station-ticket-hanzi-3","hanzi":"票","pinyin":"piào","meaning":{"en":"ticket","fr":"billet / ticket"},"explanation":{"en":"The same ticket character from the metro lesson.","fr":"Le même caractère de ticket que dans la leçon de métro."}},{"id":"train-station-ticket-hanzi-4","hanzi":"发","pinyin":"fā","meaning":{"en":"send out / depart element","fr":"envoyer / élément de départ"},"explanation":{"en":"It appears in 出发.","fr":"Il apparaît dans 出发."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
