(175, 'train-station-ticket', 'practice', '{"listening":[{"id":"train-station-ticket-listening-1","prompt":{"en":"Listen for the ticket to Shanghai.","fr":"Écoute le billet pour Shanghai."},"target":"我想买一张去上海的票。","audio":"/audio/train-station-ticket/practice-listening-01.mp3","explanation":{"en":"The destination follows 去 and comes before 的票.","fr":"La destination suit 去 et vient avant 的票."}}],"speaking":[{"id":"train-station-ticket-speaking-1","prompt":{"en":"Say that you want to buy a ticket to Shanghai.","fr":"Dis que tu veux acheter un billet pour Shanghai."},"target":"我想买一张去上海的票。","audio":"/audio/train-station-ticket/practice-speaking-01.mp3","explanation":{"en":"This is the core capstone ticketing sentence.","fr":"C’est la phrase principale de billetterie finale."}}],"reading":[{"id":"train-station-ticket-reading-1","prompt":{"en":"Read the departure time.","fr":"Lis l’heure de départ."},"target":"三点出发。","audio":"/audio/train-station-ticket/practice-reading-01.mp3","explanation":{"en":"Catch the number before 点 and 出发.","fr":"Repère le nombre avant 点 et 出发."}}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
